"use client";

import React, { useState } from 'react';
import Link from 'next/link';

export default function Header() {
  const [isNavOpen, setIsNavOpen] = useState(false);

  return (
    <nav className="fixed top-0 left-0 right-0 bg-white z-50 border-b border-gray-100 shadow-sm h-16">
        <div className="container mx-auto px-4 h-full flex items-center justify-between">
            
            {/* Logo area */}
            <div className="flex items-center gap-4">
                <Link href="/" className="flex items-center gap-2 text-decoration-none">
                    <div className="w-8 h-8 rounded-full bg-orange-500 flex items-center justify-center text-white font-bold italic shadow-sm">
                        B
                    </div>
                    <span className="font-bold text-gray-800 text-lg tracking-tight">Business tools</span>
                </Link>
                
                {/* Dark Mode Icon (Static, keeping as placeholder for logic later if needed) */}
                <button className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 transition-colors text-gray-600">
                    <i className="fas fa-moon"></i>
                </button>
            </div>

             {/* Menu Dropdown */}
            <div className="relative">
                <button 
                    onClick={() => setIsNavOpen(!isNavOpen)}
                    className="flex items-center gap-1 text-sm font-medium text-gray-600 hover:text-orange-600 transition-colors px-3 py-2 rounded-lg hover:bg-orange-50 focus:outline-none"
                    aria-label="Menu"
                >
                    Menu <i className={`fas fa-chevron-down text-xs ml-1 transition-transform ${isNavOpen ? 'rotate-180' : ''}`}></i>
                </button>

                {isNavOpen && (
                    <div className="absolute right-0 top-full mt-2 w-48 bg-white rounded-xl shadow-xl border border-gray-100 py-1 overflow-hidden z-50">
                        <Link href="/" className="block px-4 py-2 text-sm text-gray-700 hover:bg-orange-50 hover:text-orange-600" onClick={() => setIsNavOpen(false)}>Início</Link>
                        <Link href="/text-converter" className="block px-4 py-2 text-sm text-gray-700 hover:bg-orange-50 hover:text-orange-600" onClick={() => setIsNavOpen(false)}>Editor de Texto</Link>
                        <Link href="/pdf-tools" className="block px-4 py-2 text-sm text-gray-700 hover:bg-orange-50 hover:text-orange-600" onClick={() => setIsNavOpen(false)}>Ferramentas PDF</Link>
                        <Link href="/flowchart" className="block px-4 py-2 text-sm text-gray-700 hover:bg-orange-50 hover:text-orange-600" onClick={() => setIsNavOpen(false)}>Fluxograma BPMN</Link>
                    </div>
                )}
            </div>
        </div>
    </nav>
  );
}
